<?php
require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/functions.php';
requireActiveUser();requireTenantContext();requireModulePermission('operations','view');
global $conn;$tenantId=(int)getCurrentTenantId();if($tenantId<=0){http_response_code(403);exit('A valid tenant context is required.');}
$ready=flexihubTableHasColumn('field_jobs','tenant_id')&&flexihubTableHasColumn('field_jobs','assigned_staff_id')&&flexihubTableHasColumn('field_jobs','completed_at')&&flexihubTableHasColumn('staffs','tenant_id');
$from=trim((string)($_GET['from']??date('Y-m-01')));$to=trim((string)($_GET['to']??date('Y-m-d')));
$validDate=static function($v){$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);return $d&&$d->format('Y-m-d')===$v;};
if(!$validDate($from)||!$validDate($to)||$from>$to){$from=date('Y-m-01');$to=date('Y-m-d');}
$rows=[];$totals=['jobs'=>0,'completed'=>0,'open'=>0,'urgent'=>0];$errors=[];
if($ready){
 $sql="SELECT s.id,s.staff_code,s.first_name,s.last_name,s.position,COUNT(j.id) jobs_count,SUM(j.status='completed') completed_count,SUM(j.status IN ('open','scheduled','assigned','in_progress','waiting_parts')) open_count,SUM(j.priority='urgent' AND j.status NOT IN ('completed','cancelled')) urgent_count,ROUND(AVG(CASE WHEN j.completed_at IS NOT NULL THEN TIMESTAMPDIFF(HOUR,j.created_at,j.completed_at) END),1) avg_completion_hours FROM staffs s LEFT JOIN field_jobs j ON j.assigned_staff_id=s.id AND j.tenant_id=s.tenant_id AND DATE(j.created_at) BETWEEN ? AND ? WHERE s.tenant_id=? GROUP BY s.id,s.staff_code,s.first_name,s.last_name,s.position ORDER BY completed_count DESC,jobs_count DESC,s.first_name";
 $q=$conn->prepare($sql);if($q){$q->bind_param('ssi',$from,$to,$tenantId);if($q->execute()){$z=$q->get_result();while($x=$z->fetch_assoc()){$rows[]=$x;$totals['jobs']+=(int)$x['jobs_count'];$totals['completed']+=(int)$x['completed_count'];$totals['open']+=(int)$x['open_count'];$totals['urgent']+=(int)$x['urgent_count'];}}else{$errors[]='Unable to calculate technician performance.';}$q->close();}else{$errors[]='Technician performance query is unavailable.';}
}
$pageTitle='Technician Performance';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/sidebar.php';
?>
<div class="page-content"><div class="page-header"><div><h1>Technician Performance</h1><p>Tenant-scoped field-job workload and completion indicators. This is an operational summary, not a payroll or disciplinary score.</p></div><a class="btn btn-secondary" href="field_jobs.php">Field Jobs</a></div>
<?php if(!$ready):?><div class="alert alert-warning">Field operations reporting becomes available after migration 039 is installed.</div><?php endif;?><?php foreach($errors as $e):?><div class="alert alert-danger"><?=e($e)?></div><?php endforeach;?>
<form method="get" class="dashboard-card" style="padding:16px;margin-bottom:16px;display:flex;gap:12px;align-items:end;flex-wrap:wrap"><label>From<input type="date" name="from" value="<?=e($from)?>"></label><label>To<input type="date" name="to" value="<?=e($to)?>"></label><button class="btn btn-primary">Apply period</button></form>
<div class="operations-metrics"><div class="operations-metric"><span>Assigned jobs</span><strong><?=$totals['jobs']?></strong></div><div class="operations-metric"><span>Completed</span><strong><?=$totals['completed']?></strong></div><div class="operations-metric"><span>Active workload</span><strong><?=$totals['open']?></strong></div><div class="operations-metric"><span>Urgent outstanding</span><strong><?=$totals['urgent']?></strong></div></div>
<section class="dashboard-card" style="padding:18px"><div class="table-responsive"><table><thead><tr><th>Technician</th><th>Role</th><th>Jobs</th><th>Completed</th><th>Open</th><th>Urgent</th><th>Avg. completion (hours)</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e(trim($r['first_name'].' '.$r['last_name']))?></strong><small style="display:block;color:#94a3b8"><?=e($r['staff_code']??'')?></small></td><td><?=e($r['position']??'—')?></td><td><?=(int)$r['jobs_count']?></td><td><?=(int)$r['completed_count']?></td><td><?=(int)$r['open_count']?></td><td><?=(int)$r['urgent_count']?></td><td><?=e($r['avg_completion_hours']===null?'—':$r['avg_completion_hours'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">No technician job activity found for this period.</td></tr><?php endif;?></tbody></table></div></section></div>
<style>.operations-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:16px}.operations-metric{padding:17px;border:1px solid rgba(96,165,250,.14);border-radius:13px;background:linear-gradient(145deg,#101827,#0b111b)}.operations-metric span{color:#94a3b8;font-size:12px}.operations-metric strong{display:block;color:#f8fafc;font-size:25px;margin-top:8px}@media(max-width:850px){.operations-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
